options.getOption:
const series = context.panel.data.series.map((s) => {
  const sData = s.fields.find((f) => f.type === "number");
  const sTime = s.fields.find((f) => f.type === "time");
  if (!sData || !sTime) return null;
  const values = sData.values.buffer || sData.values;
  const times  = sTime.values.buffer || sTime.values;
  return {
    name: "Price (USD)",
    type: "line",
    smooth: true,
    showSymbol: false,
    lineStyle: {
      width: 2,
      color: {
        type: "linear", x: 0, y: 0, x2: 1, y2: 0,
        colorStops: [
          { offset: 0, color: "#5000BF" },
          { offset: 1, color: "#CC0AAC" },
        ],
      },
    },
    areaStyle: {
      color: {
        type: "linear", x: 0, y: 0, x2: 0, y2: 1,
        colorStops: [
          { offset: 0, color: "rgba(204, 10, 172, 0.35)" },
          { offset: 1, color: "rgba(80, 0, 191, 0.02)" },
        ],
      },
    },
    data: times.map((t, i) => [t, values[i]]),
  };
}).filter(Boolean);

return {
  backgroundColor: "transparent",
  grid: { left: 60, right: 20, top: 20, bottom: 30, containLabel: true },
  tooltip: {
    trigger: "axis",
    backgroundColor: "rgba(36, 9, 53, 0.95)",
    borderColor: "#5000BF",
    borderWidth: 1,
    textStyle: { color: "#E6E6E6", fontFamily: "Inter, sans-serif" },
    axisPointer: { lineStyle: { color: "#5000BF", type: "dashed" } },
    valueFormatter: (v) => "$" + Number(v).toFixed(6),
  },
  xAxis: {
    type: "time",
    axisLine:  { lineStyle: { color: "#3A1857" } },
    axisLabel: { color: "#A090B5", fontFamily: "Inter", fontSize: 10 },
    splitLine: { show: false },
  },
  yAxis: {
    type: "value",
    scale: true,
    axisLine:  { show: false },
    axisTick:  { show: false },
    axisLabel: {
      color: "#A090B5",
      fontFamily: "JetBrains Mono",
      fontSize: 10,
      formatter: (v) => "$" + v.toFixed(6),
    },
    splitLine: { lineStyle: { color: "rgba(58, 24, 87, 0.4)", type: "dashed" } },
  },
  series: series,
};

const frame = context.panel.data.series[0];
if (!frame || !frame.fields) return { title: { text: 'No data', textStyle: { color: '#6F4D80' }, left: 'center', top: 'middle' } };

// Extract validator addresses (from labels) and stake values
const valueField = frame.fields.find(f => f.type === 'number');
if (!valueField) return {};
const values = valueField.values.buffer || valueField.values;
const labels = valueField.labels || {};
const valueLabels = valueField.config?.displayNameFromDS || '';

// Each series in the frame has its own validator label. Since all validators
// return a single value each, we have multiple series in frame.
const series = context.panel.data.series;
const data = series.map((s, i) => {
  const numField = s.fields.find(f => f.type === 'number');
  if (!numField) return null;
  const v = (numField.values.buffer || numField.values)[0];
  // Label: try to find validator address in labels
  const lbls = numField.labels || {};
  const addr = lbls.validator || lbls.address || lbls.account || lbls.id ||
               Object.values(lbls)[0] || s.refId || ('v' + i);
  return {
    name: addr.length > 8 ? addr.slice(0, 6) + '…' + addr.slice(-4) : addr,
    fullName: addr,
    value: Number(v),
  };
}).filter(Boolean).sort((a, b) => b.value - a.value);

// Build color scale magenta->purple based on rank
const colorFor = (i, total) => {
  const t = i / Math.max(1, total - 1);
  // interpolate from magenta (#CC0AAC) to purple (#5000BF)
  const r1=0xCC, g1=0x0A, b1=0xAC;
  const r2=0x50, g2=0x00, b2=0xBF;
  const r=Math.round(r1 + (r2-r1)*t);
  const g=Math.round(g1 + (g2-g1)*t);
  const b=Math.round(b1 + (b2-b1)*t);
  return 'rgb(' + r + ',' + g + ',' + b + ')';
};

const totalStake = data.reduce((a, b) => a + b.value, 0);

return {
  backgroundColor: 'transparent',
  tooltip: {
    backgroundColor: 'rgba(36, 9, 53, 0.95)',
    borderColor: '#5000BF',
    borderWidth: 1,
    textStyle: { color: '#E6E6E6', fontFamily: 'Inter, sans-serif', fontSize: 11 },
    formatter: (info) => {
      const pct = ((info.value / totalStake) * 100).toFixed(2);
      return '<div style="padding:2px 0;">'
        + '<div style="color:#CC0AAC; font-weight:600; margin-bottom:4px;">' + (info.data.fullName || info.name) + '</div>'
        + '<div>Stake: <b>' + Number(info.value).toLocaleString('en-US') + '</b></div>'
        + '<div>Share: <b>' + pct + '%</b></div>'
        + '</div>';
    },
  },
  series: [{
    type: 'treemap',
    data: data.map((d, i) => ({
      ...d,
      itemStyle: { color: colorFor(i, data.length) },
    })),
    roam: false,
    nodeClick: false,
    breadcrumb: { show: false },
    label: {
      show: true,
      formatter: '{b}',
      color: '#E6E6E6',
      fontFamily: 'JetBrains Mono, monospace',
      fontSize: 10,
      fontWeight: 600,
      textShadowColor: 'rgba(0,0,0,0.8)',
      textShadowBlur: 4,
    },
    upperLabel: { show: false },
    itemStyle: {
      borderColor: 'rgba(16, 2, 23, 0.9)',
      borderWidth: 2,
      gapWidth: 2,
    },
    emphasis: {
      itemStyle: {
        shadowBlur: 20,
        shadowColor: 'rgba(204, 10, 172, 0.6)',
      },
      label: { fontSize: 13 },
    },
    levels: [{
      itemStyle: {
        borderColor: 'rgba(16, 2, 23, 0.9)',
        borderWidth: 2,
        gapWidth: 2,
      },
    }],
  }],
};

const series = context.panel.data.series;
const data = series.map((s, i) => {
  const numField = s.fields.find(f => f.type === 'number');
  if (!numField) return null;
  const v = (numField.values.buffer || numField.values)[0];
  const lbls = numField.labels || {};
  const addr = lbls.validator || lbls.address || lbls.account || lbls.id ||
               Object.values(lbls)[0] || s.refId || ('v' + i);
  return {
    name: addr.length > 8 ? addr.slice(0, 6) + '…' + addr.slice(-4) : addr,
    fullName: addr,
    value: Number(v),
  };
}).filter(Boolean).sort((a, b) => a.value - b.value);  // ascending for horizontal bar

return {
  backgroundColor: 'transparent',
  grid: { left: 110, right: 30, top: 10, bottom: 30, containLabel: false },
  tooltip: {
    trigger: 'item',
    backgroundColor: 'rgba(36, 9, 53, 0.95)',
    borderColor: '#5000BF',
    borderWidth: 1,
    textStyle: { color: '#E6E6E6', fontFamily: 'Inter' },
    formatter: (p) => '<b style="color:#CC0AAC">' + (p.data.fullName || p.name) + '</b><br/>Era points: <b>' + Number(p.value).toLocaleString('en-US') + '</b>',
  },
  xAxis: {
    type: 'value',
    axisLine:  { show: false },
    axisTick:  { show: false },
    axisLabel: { color: '#A090B5', fontFamily: 'JetBrains Mono', fontSize: 9 },
    splitLine: { lineStyle: { color: 'rgba(58, 24, 87, 0.4)', type: 'dashed' } },
  },
  yAxis: {
    type: 'category',
    data: data.map(d => d.name),
    axisLine:  { lineStyle: { color: '#3A1857' } },
    axisTick:  { show: false },
    axisLabel: { color: '#A090B5', fontFamily: 'JetBrains Mono', fontSize: 9 },
  },
  series: [{
    type: 'bar',
    data: data.map(d => ({ value: d.value, fullName: d.fullName })),
    itemStyle: {
      color: {
        type: 'linear', x: 0, y: 0, x2: 1, y2: 0,
        colorStops: [
          { offset: 0, color: '#5000BF' },
          { offset: 1, color: '#CC0AAC' },
        ],
      },
      borderRadius: [0, 3, 3, 0],
    },
    emphasis: {
      itemStyle: { shadowBlur: 10, shadowColor: 'rgba(204, 10, 172, 0.6)' },
    },
    barWidth: '70%',
  }],
};

const s = context.panel.data.series;
const W = context.panel.chart.getWidth();

if (!s || !s.length) {
  return {backgroundColor:'transparent', graphic:{elements:[
    {type:'text', left:'center', top:'center', style:{text:'No validator data', fill:'#6F4D80', fontSize:14}}
  ]}};
}

// Merge 6 Prometheus series by validator address label
// Each series has refId: Stake/OwnStake/Commission/Nominators/Points/Active
const byValidator = new Map();
const refToKey = {
  'Stake': 'stake', 'OwnStake': 'ownStake', 'Commission': 'commission',
  'Nominators': 'nominators', 'Points': 'points', 'Active': 'active',
};

s.forEach(serie => {
  const key = refToKey[serie.refId];
  if (!key) return;
  const numField = serie.fields.find(f => f.type === 'number');
  if (!numField) return;
  const v = (numField.values.buffer || numField.values)[0];
  const lbls = numField.labels || {};
  const addr = lbls.validator || lbls.address || lbls.account || lbls.id ||
               Object.values(lbls)[0];
  if (!addr) return;
  if (!byValidator.has(addr)) byValidator.set(addr, {addr});
  byValidator.get(addr)[key] = Number(v);
});

const rows = Array.from(byValidator.values()).map(r => ({
  addr: r.addr,
  stake: r.stake ?? 0,
  ownStake: r.ownStake ?? 0,
  commission: r.commission ?? 0,
  nominators: r.nominators ?? 0,
  points: r.points ?? 0,
  active: r.active ?? 0,
}));

if (!rows.length) {
  return {backgroundColor:'transparent', graphic:{elements:[
    {type:'text', left:'center', top:'center', style:{text:'No validator data', fill:'#6F4D80', fontSize:14}}
  ]}};
}

// Stats for header
const activeN = rows.filter(r => r.active === 1).length;
const waitingN = rows.filter(r => r.active === 0).length;
const totalStake = rows.reduce((a,r) => a + r.stake, 0);
const totalNominators = rows.reduce((a,r) => a + r.nominators, 0);
const avgCommission = rows.reduce((a,r) => a + r.commission, 0) / rows.length;

const fmt = n => Number(n).toLocaleString('en-US', {maximumFractionDigits: 0});
const fmtPct = n => (n * 100).toFixed(1) + '%';

const shortAddr = a => a.length > 14 ? a.slice(0,8) + '…' + a.slice(-4) : a;

const dom = context.panel.chart.getDom();
dom._sxtRows = rows;
dom._sxtSortCol = dom._sxtSortCol || 'stake';
dom._sxtSortDir = dom._sxtSortDir || 'desc';

function buildTable(sortCol, sortDir) {
  const sorted = [...dom._sxtRows];
  sorted.sort((a, b) => {
    let cmp;
    if (sortCol === 'addr') cmp = a.addr.localeCompare(b.addr);
    else cmp = (a[sortCol] || 0) - (b[sortCol] || 0);
    return sortDir === 'asc' ? cmp : -cmp;
  });

  const maxStake = Math.max(...sorted.map(r => r.stake));
  const maxPoints = Math.max(...sorted.map(r => r.points));

  const arrow = col => sortCol === col
    ? (sortDir === 'asc' ? ' ▲' : ' ▼')
    : ' ▴▾';
  const headColor = col => sortCol === col ? '#CC0AAC' : '#A090B5';

  // Header with summary stats
  let h = '<div style="display:flex;gap:18px;padding:10px 16px;border-bottom:1px solid #3A1857;font-size:11px;color:#A090B5;font-family:Inter,sans-serif;">';
  h += '<span><span style="color:#22c55e">●</span> Active: <b style="color:#E6E6E6">'+activeN+'</b></span>';
  if (waitingN > 0) h += '<span><span style="color:#6F4D80">●</span> Waiting: <b style="color:#E6E6E6">'+waitingN+'</b></span>';
  h += '<span style="margin-left:auto">Total stake: <b style="color:#CC0AAC">'+fmt(totalStake)+'</b> SXT</span>';
  h += '<span>Nominators: <b style="color:#E6E6E6">'+fmt(totalNominators)+'</b></span>';
  h += '<span>Avg commission: <b style="color:#E6E6E6">'+fmtPct(avgCommission)+'</b></span>';
  h += '<span style="color:#6F4D80">Total: '+sorted.length+'</span>';
  h += '</div>';

  // Table
  h += '<table style="width:100%;border-collapse:collapse;font-size:12px;color:#E6E6E6;">';
  h += '<thead style="position:sticky;top:0;z-index:1;">';
  h += '<tr style="background:#100217;">';
  h += '<th data-sort="addr"       style="cursor:pointer;user-select:none;text-align:left;padding:8px 14px;color:'+headColor('addr')+';font-size:10px;font-weight:600;letter-spacing:1px;border-bottom:1px solid #3A1857;">VALIDATOR'+arrow('addr')+'</th>';
  h += '<th data-sort="active"     style="cursor:pointer;user-select:none;text-align:center;padding:8px 14px;color:'+headColor('active')+';font-size:10px;font-weight:600;letter-spacing:1px;border-bottom:1px solid #3A1857;">STATUS'+arrow('active')+'</th>';
  h += '<th data-sort="stake"      style="cursor:pointer;user-select:none;text-align:right;padding:8px 14px;color:'+headColor('stake')+';font-size:10px;font-weight:600;letter-spacing:1px;border-bottom:1px solid #3A1857;">TOTAL STAKE'+arrow('stake')+'</th>';
  h += '<th data-sort="ownStake"   style="cursor:pointer;user-select:none;text-align:right;padding:8px 14px;color:'+headColor('ownStake')+';font-size:10px;font-weight:600;letter-spacing:1px;border-bottom:1px solid #3A1857;">OWN STAKE'+arrow('ownStake')+'</th>';
  h += '<th data-sort="commission" style="cursor:pointer;user-select:none;text-align:right;padding:8px 14px;color:'+headColor('commission')+';font-size:10px;font-weight:600;letter-spacing:1px;border-bottom:1px solid #3A1857;">COMMISSION'+arrow('commission')+'</th>';
  h += '<th data-sort="nominators" style="cursor:pointer;user-select:none;text-align:right;padding:8px 14px;color:'+headColor('nominators')+';font-size:10px;font-weight:600;letter-spacing:1px;border-bottom:1px solid #3A1857;">NOMINATORS'+arrow('nominators')+'</th>';
  h += '<th data-sort="points"     style="cursor:pointer;user-select:none;text-align:right;padding:8px 14px;color:'+headColor('points')+';font-size:10px;font-weight:600;letter-spacing:1px;border-bottom:1px solid #3A1857;">ERA POINTS'+arrow('points')+'</th>';
  h += '</tr></thead><tbody>';

  for (let i = 0; i < sorted.length; i++) {
    const r = sorted[i];
    const bg = i % 2 === 0 ? 'transparent' : 'rgba(204,10,172,0.025)';
    const stakePct = Math.min(100, (r.stake / maxStake) * 100);
    const pointsPct = Math.min(100, (r.points / maxPoints) * 100);
    const statusLabel = r.active === 1 ? 'Active' : 'Waiting';
    const statusColor = r.active === 1 ? '#22c55e' : '#6F4D80';
    const statusIcon = r.active === 1 ? '●' : '○';

    h += '<tr style="background:'+bg+'" onmouseover="this.style.background=\'rgba(204,10,172,0.08)\'" onmouseout="this.style.background=\''+bg+'\'">';
    h += '<td style="padding:7px 14px;font-family:JetBrains Mono,monospace;font-size:11px;color:#E6E6E6;">'+shortAddr(r.addr)+'</td>';
    h += '<td style="padding:7px 14px;text-align:center;color:'+statusColor+';font-size:11px;font-weight:500;">'+statusIcon+' '+statusLabel+'</td>';

    h += '<td style="padding:7px 14px;text-align:right;"><div style="display:flex;align-items:center;justify-content:flex-end;gap:10px;">';
    h += '<div style="width:70px;height:4px;background:rgba(58,24,87,0.4);border-radius:2px;overflow:hidden;"><div style="width:'+stakePct+'%;height:100%;background:linear-gradient(90deg,#5000BF,#CC0AAC);border-radius:2px;"></div></div>';
    h += '<span style="color:#E6E6E6;font-family:JetBrains Mono,monospace;font-size:11px;font-weight:600;min-width:100px;text-align:right;">'+fmt(r.stake)+'</span></div></td>';

    h += '<td style="padding:7px 14px;text-align:right;font-family:JetBrains Mono,monospace;font-size:11px;color:#A090B5;">'+fmt(r.ownStake)+'</td>';
    h += '<td style="padding:7px 14px;text-align:right;font-family:JetBrains Mono,monospace;font-size:11px;color:#A090B5;">'+fmtPct(r.commission)+'</td>';
    h += '<td style="padding:7px 14px;text-align:right;font-family:JetBrains Mono,monospace;font-size:11px;color:#A090B5;">'+fmt(r.nominators)+'</td>';

    h += '<td style="padding:7px 14px;text-align:right;"><div style="display:flex;align-items:center;justify-content:flex-end;gap:10px;">';
    h += '<div style="width:60px;height:4px;background:rgba(58,24,87,0.4);border-radius:2px;overflow:hidden;"><div style="width:'+pointsPct+'%;height:100%;background:#CC0AAC;border-radius:2px;"></div></div>';
    h += '<span style="color:#E6E6E6;font-family:JetBrains Mono,monospace;font-size:11px;font-weight:600;min-width:60px;text-align:right;">'+fmt(r.points)+'</span></div></td>';

    h += '</tr>';
  }
  h += '</tbody></table>';
  return h;
}

dom._sxtBuildTable = buildTable;
const html = buildTable(dom._sxtSortCol, dom._sxtSortDir);
const _hash = html.length + '_' + dom._sxtSortCol + dom._sxtSortDir;
if (dom._lastSxtHash === _hash) return {backgroundColor:'transparent'};
dom._lastSxtHash = _hash;

setTimeout(() => {
  let wrap = dom.querySelector('.sxt-val-wrap');
  if (!wrap) {
    wrap = document.createElement('div');
    wrap.className = 'sxt-val-wrap';
    wrap.style.cssText = 'position:absolute;inset:0;overflow-y:auto;overflow-x:hidden;z-index:10;scrollbar-width:thin;scrollbar-color:#3A1857 transparent;';
    dom.appendChild(wrap);
  }
  wrap.innerHTML = html;

  dom._sxtAttachSort = function(w) {
    w.querySelectorAll('[data-sort]').forEach(th => {
      th.addEventListener('click', function() {
        const col = this.getAttribute('data-sort');
        if (dom._sxtSortCol === col) {
          dom._sxtSortDir = dom._sxtSortDir === 'asc' ? 'desc' : 'asc';
        } else {
          dom._sxtSortCol = col;
          dom._sxtSortDir = col === 'addr' ? 'asc' : 'desc';
        }
        w.innerHTML = dom._sxtBuildTable(dom._sxtSortCol, dom._sxtSortDir);
        dom._lastSxtHash = null;
        dom._sxtAttachSort(w);
      });
    });
  };
  dom._sxtAttachSort(wrap);
}, 0);

return {backgroundColor:'transparent'};

const series = context.panel.data.series;
const data = series.map((s, i) => {
  const numField = s.fields.find(f => f.type === 'number');
  if (!numField) return null;
  const v = (numField.values.buffer || numField.values)[0];
  const lbls = numField.labels || {};
  const addr = lbls.validator || lbls.address || lbls.account || lbls.id ||
               Object.values(lbls)[0] || s.refId || ('v' + i);
  return {
    name: addr.length > 8 ? addr.slice(0, 6) + '…' + addr.slice(-4) : addr,
    fullName: addr,
    value: Number(v),
  };
}).filter(Boolean).sort((a, b) => b.value - a.value);

// Top 10 + "Others" aggregation
const TOP = 10;
let pieData = data;
if (data.length > TOP) {
  const top = data.slice(0, TOP);
  const others = data.slice(TOP).reduce((sum, d) => sum + d.value, 0);
  pieData = [...top, { name: 'Others (' + (data.length - TOP) + ')', fullName: 'Others', value: others }];
}

const colorFor = (i, total) => {
  const t = i / Math.max(1, total - 1);
  const r1=0xCC, g1=0x0A, b1=0xAC;
  const r2=0x50, g2=0x00, b2=0xBF;
  const r=Math.round(r1 + (r2-r1)*t);
  const g=Math.round(g1 + (g2-g1)*t);
  const b=Math.round(b1 + (b2-b1)*t);
  return 'rgb(' + r + ',' + g + ',' + b + ')';
};

return {
  backgroundColor: 'transparent',
  tooltip: {
    trigger: 'item',
    backgroundColor: 'rgba(36, 9, 53, 0.95)',
    borderColor: '#5000BF',
    borderWidth: 1,
    textStyle: { color: '#E6E6E6', fontFamily: 'Inter' },
    formatter: (p) => '<b style="color:#CC0AAC">' + (p.data.fullName || p.name) + '</b><br/>Stake: <b>$' + Number(p.value).toLocaleString('en-US') + '</b><br/>Share: <b>' + p.percent + '%</b>',
  },
  series: [{
    type: 'pie',
    radius: ['40%', '70%'],
    center: ['50%', '50%'],
    avoidLabelOverlap: true,
    itemStyle: {
      borderColor: 'rgba(16, 2, 23, 0.9)',
      borderWidth: 2,
    },
    label: {
      show: true,
      color: '#E6E6E6',
      fontFamily: 'JetBrains Mono, monospace',
      fontSize: 9,
      formatter: '{b}',
    },
    labelLine: { lineStyle: { color: '#6F4D80' } },
    emphasis: {
      itemStyle: { shadowBlur: 15, shadowColor: 'rgba(204, 10, 172, 0.6)' },
      label: { fontSize: 11, fontWeight: 'bold' },
    },
    data: pieData.map((d, i) => ({
      ...d,
      itemStyle: { color: colorFor(i, pieData.length) },
    })),
  }],
};

const frame = context.panel.data.series[0];
if (!frame) return { title: { text: 'No data', left: 'center', top: 'middle', textStyle: { color: '#6F4D80' } } };

const eraField = frame.fields.find(f => f.name === 'era');
const rewardField = frame.fields.find(f => f.name === 'network_reward' || f.type === 'number');
if (!eraField || !rewardField) return {};

const eras = eraField.values.buffer || eraField.values;
const rewards = rewardField.values.buffer || rewardField.values;

return {
  backgroundColor: 'transparent',
  grid: { left: 60, right: 20, top: 20, bottom: 40, containLabel: true },
  tooltip: {
    trigger: 'axis',
    backgroundColor: 'rgba(36, 9, 53, 0.95)',
    borderColor: '#5000BF',
    borderWidth: 1,
    textStyle: { color: '#E6E6E6', fontFamily: 'Inter' },
    formatter: (params) => {
      const p = params[0];
      return '<b style="color:#CC0AAC">Era ' + p.name + '</b><br/>Reward: <b>' + Number(p.value).toLocaleString('en-US') + '</b>';
    },
    axisPointer: { type: 'shadow', shadowStyle: { color: 'rgba(204, 10, 172, 0.1)' } },
  },
  xAxis: {
    type: 'category',
    data: eras.map(e => String(e)),
    axisLine:  { lineStyle: { color: '#3A1857' } },
    axisTick:  { show: false },
    axisLabel: { color: '#A090B5', fontFamily: 'JetBrains Mono', fontSize: 9 },
  },
  yAxis: {
    type: 'value',
    axisLine:  { show: false },
